import{_ as a,o as t,c as s,a3 as l}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"模型与消息","description":"讲清 LangChain 模型接口、消息协议和结构化结果三层契约。","frontmatter":{"title":"模型与消息","description":"讲清 LangChain 模型接口、消息协议和结构化结果三层契约。"},"headers":[],"relativePath":"py-agent/agent/models-messages/index.md","filePath":"py-agent/agent/models-messages/index.md","lastUpdated":1785314595000}'),o={name:"py-agent/agent/models-messages/index.md"};function n(i,e,r,d,h,m){return t(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="模型与消息" tabindex="-1">模型与消息 <a class="header-anchor" href="#模型与消息" aria-label="Permalink to &quot;模型与消息&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>模型是 Agent 的决策组件，消息是模型与应用之间的协议，结构化输出是结果契约。本分组按这三层展开，避免把 Prompt 字符串、SDK 响应和业务结果混为一谈。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>初始化并调用 LangChain Chat Model；</li><li>区分 System、Human、AI 和 Tool Message 的职责；</li><li>正确关联工具请求与 ToolMessage；</li><li>使用 Schema 获得结构化模型或 Agent 结果；</li><li>区分生成约束、Schema 校验和业务校验。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/agent/models-messages/chat-models">Chat Models</a>：模型接口、调用方式和能力绑定。</li><li><a href="/py-agent/agent/models-messages/messages">Messages</a>：角色、内容块、元数据和工具消息协议。</li><li><a href="/py-agent/agent/models-messages/structured-output">结构化输出</a>：Schema、生成策略和结果验收。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>本组不讨论 Agent 状态持久化，也不把供应商 SDK 的所有字段逐项罗列。目标是建立 LangChain Agent 后续共同使用的模型与消息契约。</p>',10)])])}const p=a(o,[["render",n]]);export{c as __pageData,p as default};
